    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict[str, str]:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    # ACC-001 ON ACCT_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_len(_value(record, "ACCT_NM")) >= 2):
            errors.append(_failure("E1001", "Account name too short"))

    # ACC-002 ON ACCT_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append(_failure("E1002", "Invalid account type"))

    # ACC-003 ON ACCT_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(_value(record, "ANN_REV"), 0)) >= Decimal(0)):
            errors.append(_failure("E1003", "Annual revenue negative"))

    # ACC-004 ON ACCT_MASTER WHEN UPDATE
    if event == "UPDATE":
        old_credit_hold = _value(old, "CRED_HOLD")
        new_credit_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))
        expression = not (
            old_credit_hold == "Y"
            and new_credit_hold == "N"
            and credit_limit <= Decimal(0)
        )
        if not expression:
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005 ON ACCT_MASTER WHEN INSERT,UPDATE
    if event in ("INSERT", "UPDATE"):
        if not (_len(_value(record, "REGION_CD")) == 3):
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
